<script lang="ts">
import {translatedName} from './localization';

 import {languageOverrides} from "./localization";
 import {uiLabel} from "./english";
 import {onDestroy} from 'svelte';import type {Project} from './model';import {uid} from './model';import type {AdministrationDocument,AdministrationKind} from './administration-schema';import {makeAdministrationDocument,administrationRow,saveAdministrationDocument,unpostAdministrationDocument,markAdministrationDocument} from './administration';import {activeBenefits,buildingServices} from './administration-data';import {accountOpenInMonth} from './account-lifecycle';import {catalogFields} from './catalog-definitions';import {displayDate} from './date-format';import {reportEditorDirty} from './editor-drafts';import {openReportLookup} from './report-settings';import {translator} from './i18n';import RecordToolbar from './RecordToolbar.svelte';import LineToolbar from './LineToolbar.svelte';import AccountLookupField from './AccountLookupField.svelte';import {Check,Save,X,FileText,Calculator} from '@lucide/svelte';import {D,money} from './engine';
 export let project:Project;export let kind:AdministrationKind;export let initial:AdministrationDocument|null=null;export let editorId='';export let onapply:(p:Project)=>void;export let onedit:(d:AdministrationDocument)=>void;export let onclose:()=>void;export let onmovements:(d:AdministrationDocument)=>void;export let beforeChange:(id:string)=>Promise<boolean>=async()=>true;
 let page=1,tab='main',draft=initial?structuredClone(initial):null,selected='',rowIndex=0,search='',filterOpen=false,state='all',error='',saved=JSON.stringify(draft);
 if(draft&&kind==='recalculation'&&!draft.recalculation_period){const d=new Date(draft.period+'-01T00:00:00Z');d.setUTCDate(0);draft.recalculation_period=d.toISOString().slice(0,7);}
 $:t=translator(project.settings.language,$languageOverrides);$:locked=draft?.state==='applied'||draft?.imported;$:rows=project.administration.documents.filter(d=>d.kind===kind&&(state==='all'||d.state===state)&&(d.number+' '+d.date+' '+d.comment+' '+(project.reference_catalogs.buildings?.find(b=>b.id===d.building_id)?.name||'')+' '+(project.reference_catalogs.citizens?.find(c=>c.id===d.citizen_id)?.name||'')).toLocaleLowerCase().includes(search.toLocaleLowerCase()));$:pages=Math.max(1,Math.ceil(rows.length/100));$:page=Math.min(page,pages);$:current=rows.find(d=>d.id===selected);$:benefit=kind==='grant-benefits'||kind==='end-benefits';$:financial=['service-charges','recalculation','charge-corrections','penalties'].includes(kind);$:charge=['service-charges','recalculation'].includes(kind);$:reportEditorDirty(editorId,!!draft&&!locked&&(!project.administration.documents.some(d=>d.id===draft?.id)||JSON.stringify(draft)!==saved));
 onDestroy(()=>reportEditorDirty(editorId,false));
 function create(){onedit(makeAdministrationDocument(project,kind));}
 function copy(){if(!current)return;const d=makeAdministrationDocument(project,kind);d.comment=current.comment;d.correction_type=current.correction_type;d.recalculation_period=current.recalculation_period;d.recalculate_services=current.recalculate_services;d.recalculate_benefits=current.recalculate_benefits;d.building_id=current.building_id;d.citizen_id=current.citizen_id;d.person_name=current.person_name;d.person_attributes=structuredClone(current.person_attributes);d.rows=current.rows.map(r=>({...r,id:uid()}));onedit(d);}
 async function act(action:'post'|'unpost'|'mark'){if(!current||!await beforeChange(current.id))return;try{onapply(action==='post'?saveAdministrationDocument(project,current,true):action==='unpost'?unpostAdministrationDocument(project,current.id):markAdministrationDocument(project,current.id));error='';}catch(e){error=e instanceof Error?e.message:String(e);}}
 function save(post=false,close=false){if(!draft)return;try{const next=saveAdministrationDocument(project,draft,post);onapply(next);draft=structuredClone(next.administration.documents.find(d=>d.id===draft!.id)!);saved=JSON.stringify(draft);reportEditorDirty(editorId,false);error='';if(close)onclose();}catch(e){error=e instanceof Error?e.message:String(e);}}
 function add(){if(draft){draft.rows=[...draft.rows,{...administrationRow(project),effective_from:draft.date,citizen_id:draft.citizen_id,category_id:draft.rows[0]?.category_id||''}];rowIndex=draft.rows.length-1;}}
 function move(delta:number){if(!draft)return;const next=rowIndex+delta;if(next<0||next>=draft.rows.length)return;const rows=[...draft.rows];[rows[next],rows[rowIndex]]=[rows[rowIndex],rows[next]];draft.rows=rows;rowIndex=next;}
 function fill(){if(!draft)return;if(kind==='citizen-changes'){const latest=new Map<string,Project['account_history']['relationships'][number]>();for(const r of project.account_history.relationships.filter(r=>r.citizen_id===draft!.citizen_id&&r.date<=draft!.date).sort((a,b)=>a.date.localeCompare(b.date)))latest.set(r.relative_id,r);draft.rows=[...latest.values()].map(r=>({...administrationRow(project),relative_id:r.relative_id,relationship_id:r.relationship_id,active:r.active!==false,effective_from:draft!.date}));}else if(kind==='building-services'){const current=buildingServices(project,draft.building_id,draft.date);draft.rows=project.services.filter(s=>s.active).map(s=>({...administrationRow(project),effective_from:draft!.date,service_id:s.id,tariff_type_id:current.find(r=>r.service_id===s.id)?.tariff_type_id||'',active:current.find(r=>r.service_id===s.id)?.active??true}));}else if(kind==='end-benefits'){draft.rows=activeBenefits(project,draft.date).map(b=>({...administrationRow(project),effective_from:draft!.date,benefit_id:b.id,account_id:b.account_id,citizen_id:b.citizen_id,service_id:b.service_id,category_id:b.category_id}));}else if(financial){draft.rows=project.accounts.filter(a=>accountOpenInMonth(a,draft!.period)).map(a=>({...administrationRow(project),effective_from:draft!.date,account_id:a.id}));}}
 function pick(){if(!draft)return;const items=kind==='citizen-changes'?(project.reference_catalogs.citizens||[]).filter(c=>c.id!==draft!.citizen_id).map(c=>({id:c.id,code:c.code,name:c.name})):kind==='building-services'?project.services.map(s=>({id:s.id,code:'',name:translatedName(s.name,project.settings.language,$languageOverrides)})):kind==='end-benefits'?activeBenefits(project,draft.date).map(b=>({id:b.id,code:project.accounts.find(a=>a.id===b.account_id)?.number||'',name:(project.reference_catalogs.citizens?.find(c=>c.id===b.citizen_id)?.name||b.citizen_id)+' · '+(project.services.find(s=>s.id===b.service_id)?.name[project.settings.language]||'')})):project.accounts.map(a=>({id:a.id,code:a.number,name:a.payer_name,address:a.address}));openReportLookup({id:editorId+'-rows',parentId:editorId,label:t('Подбор','Selectare'),items,selected:[],multiple:true,onchoose:ids=>{if(!draft||locked)return;for(const id of ids){const row={...administrationRow(project),effective_from:draft.date,citizen_id:draft.citizen_id,category_id:draft.rows[0]?.category_id||''};if(kind==='citizen-changes')row.relative_id=id;else if(kind==='building-services')row.service_id=id;else if(kind==='end-benefits'){const b=activeBenefits(project,draft.date).find(b=>b.id===id);if(!b)continue;Object.assign(row,{benefit_id:b.id,account_id:b.account_id,citizen_id:b.citizen_id,service_id:b.service_id,category_id:b.category_id});}else row.account_id=id;draft.rows=[...draft.rows,row];}}});}
 function penaltyPreview(quantity:string,rate:string,days:number){try{return money(D(quantity||0).times(rate||0).div(100).times(days||0),project);}catch{return '—';}}
 function person(id:string){if(!draft)return;const citizen=project.reference_catalogs.citizens?.find(c=>c.id===id);draft.citizen_id=id;draft.person_name=citizen?.name||'';if(kind==='citizen-changes')draft.person_attributes=structuredClone(citizen?.attributes||{});if(benefit)for(const row of draft.rows)row.citizen_id=id;}
</script>
<div class="administration-documents">
{#if error}<p role="alert" class="alert error">{error}</p>{/if}
{#if !draft}<RecordToolbar language={project.settings.language} selected={!!current} onadd={create} oncopy={copy} onedit={()=>current&&onedit(structuredClone(current))} onremove={()=>act('mark')} onrefresh={()=>{error='';selected='';}} onfilter={()=>filterOpen=!filterOpen} onclearfilter={()=>{search='';state='all';}} filterActive={!!search||state!=='all'} onpost={()=>act('post')} canPost={current?.state==='draft'&&!current?.marked_for_deletion&&!current?.imported} onunpost={()=>act('unpost')} canUnpost={current?.state==='applied'&&!current?.imported} onmovements={()=>current&&onmovements(current)}/>
{#if filterOpen}<div class="filters"><label>{t('Поиск','Căutare')}<input bind:value={search}/></label><label>{t('Статус','Stare')}<select bind:value={state}><option value="all">{t('Все','Toate')}</option><option value="draft">{t('Черновик','Ciornă')}</option><option value="applied">{t('Проведён','Aplicat')}</option></select></label></div>{/if}
<div class="table-wrap"><table><thead><tr><th>{t('Дата','Data')}</th><th>{t('Номер','Număr')}</th>{#if financial&&kind!=='charge-corrections'}<th>{t('Лицевой счёт','Cont personal')}</th>{/if}{#if kind==='building-services'}<th>{t('Здание','Clădire')}</th>{/if}{#if ['citizen-changes','grant-benefits','end-benefits'].includes(kind)}<th>{t('Гражданин','Persoană')}</th>{/if}<th>{t('Комментарий','Comentariu')}</th><th>{t('Статус','Stare')}</th></tr></thead><tbody>{#each rows.slice((page-1)*100,page*100) as d}<tr class:selected={selected===d.id} class:attention-row={d.state==='draft'} class:marked={d.marked_for_deletion} onclick={()=>selected=d.id} ondblclick={()=>onedit(structuredClone(d))}><td>{displayDate(d.date,project)}</td><td>{d.number}</td>{#if financial&&kind!=='charge-corrections'}<td>{project.accounts.find(a=>a.id===d.rows[0]?.account_id)?.number||''}</td>{/if}{#if kind==='building-services'}<td>{project.reference_catalogs.buildings?.find(b=>b.id===d.building_id)?.name||''}</td>{/if}{#if ['citizen-changes','grant-benefits','end-benefits'].includes(kind)}<td>{project.reference_catalogs.citizens?.find(c=>c.id===d.citizen_id)?.name||''}</td>{/if}<td>{d.comment}</td><td>{d.marked_for_deletion?t('Помечен на удаление','Marcat pentru ștergere'):d.state==='applied'?t('Проведён','Aplicat'):t('Черновик','Ciornă')}</td></tr>{/each}</tbody></table></div>
<div class="journal-pages"><span>{t('Записей: ','Înregistrări: ')}{rows.length}</span><button disabled={page===1} onclick={()=>{page--;selected='';}}>‹</button><span>{page} / {pages}</span><button disabled={page===pages} onclick={()=>{page++;selected='';}}>›</button></div>
{:else}
<div class="document-head"><label>{t('Дата','Data')}<input type="date" bind:value={draft.date} disabled={locked}/></label><label>{t('Номер','Număr')}<input bind:value={draft.number} disabled={locked}/></label>{#if financial}<label>{t('Расчётный период','Perioadă de calcul')}<input type="month" bind:value={draft.period} disabled={locked}/></label>{/if}</div>
{#if kind==='charge-corrections'}<label class="wide-field">{t('Вид корректировки','Tip de ajustare')}<select bind:value={draft.correction_type} disabled={locked}><option value="charges">{t('Корректировка начислений','Ajustare calcule')}</option><option value="benefits">{t('Корректировка льгот','Ajustare facilități')}</option><option value="penalties">{t('Корректировка пени','Ajustare penalități')}</option><option value="advance">{t('Корректировка аванса','Ajustare avans')}</option><option value="payment">{t('Корректировка оплаты','Ajustare plată')}</option></select></label><p class="quiet-note">{['benefits','advance','payment'].includes(draft.correction_type)?t('Положительная сумма увеличивает льготу, аванс или учтённую оплату и уменьшает долг. Это корректировка сальдо, без движения денег в банке или кассе.','Suma pozitivă mărește facilitatea, avansul sau plata contabilizată și reduce datoria. Este o ajustare de sold, fără mișcare de numerar.'):t('Положительная сумма увеличивает долг, отрицательная — уменьшает.','Suma pozitivă mărește datoria, cea negativă o reduce.')}</p>{/if}
{#if kind==='recalculation'}<label class="wide-field">{t('Лицевой счёт','Cont personal')}<AccountLookupField {project} kind="accounts" value={draft.rows[0]?.account_id||''} parentId={editorId} disabled={locked} onselect={id=>{if(draft){if(!draft.rows.length)draft.rows=[administrationRow(project)];draft.rows=draft.rows.map(r=>({...r,account_id:id}));}}}/></label><label class="wide-field">{t('Перерассчитываемый период','Perioada recalculată')}<input type="month" value={draft.recalculation_period||draft.period} disabled={locked} onchange={e=>{if(draft)draft.recalculation_period=e.currentTarget.value;}}/></label><label class="check-row"><input type="checkbox" bind:checked={draft.recalculate_services} disabled={locked}/>{t('Перерассчитывать услуги','Recalculează serviciile')}</label><label class="check-row"><input type="checkbox" bind:checked={draft.recalculate_benefits} disabled={locked}/>{t('Перерассчитывать льготы','Recalculează facilitățile')}</label>{#if draft.recalculation_period&&draft.recalculation_period!==draft.period}<p class="quiet-note">{t('Разница будет проведена в текущем месяце. Сохранённое начисление прошлого месяца не переписывается.','Diferența va fi aplicată în luna curentă. Calculul păstrat pentru luna anterioară nu se rescrie.')}</p>{/if}{/if}
{#if kind==='building-services'}<label class="wide-field">{t('Здание','Clădire')}<AccountLookupField {project} kind="buildings" value={draft.building_id} parentId={editorId} disabled={locked} onselect={id=>{if(draft)draft.building_id=id;}}/></label>{/if}
{#if benefit}<label class="wide-field">{t('Гражданин','Persoană')}<AccountLookupField {project} kind="citizens" value={draft.citizen_id} parentId={editorId} disabled={locked} onselect={person}/></label><nav class="document-tabs"><button class:chosen={tab==='main'} onclick={()=>tab='main'}>{t('Основное','Principal')}</button><button class:chosen={tab==='billing'} onclick={()=>tab='billing'}>{t('Расчёт по услугам','Calcul pe servicii')}</button></nav>{#if tab==='main'&&draft.rows[0]}{@const first=draft.rows[0]}{#if kind==='grant-benefits'}<label class="wide-field">{t('Категория льготы','Categoria facilității')}<AccountLookupField {project} kind="benefit-categories" value={first.category_id} parentId={editorId} disabled={locked} onselect={id=>{if(draft)for(const row of draft.rows)row.category_id=id;}}/></label><label class="wide-field">{t('Дата начала действия льготы','Valabil de la')}<input type="date" value={first.effective_from} disabled={locked} onchange={e=>{if(draft)for(const row of draft.rows)row.effective_from=e.currentTarget.value;}}/></label><label class="wide-field">{t('Дата окончания действия льготы','Valabil până la')}<input type="date" value={first.until||''} disabled={locked} onchange={e=>{if(draft)for(const row of draft.rows)row.until=e.currentTarget.value||null;}}/></label><fieldset><legend>{t('Документ на льготу','Document justificativ')}</legend><label class="wide-field">{t('Вид документа','Tip document')}<AccountLookupField {project} kind="benefit-documents" value={draft.person_attributes.document_type||''} parentId={editorId} disabled={locked} onselect={id=>{if(draft)draft.person_attributes.document_type=id;}}/></label>{#each [['series','Серия','Serie'],['number','Номер','Număr'],['issued_on','Дата выдачи','Data eliberării'],['issuer','Кем выдан','Eliberat de']] as field}<label class="wide-field">{t(field[1],field[2])}<input type={field[0]==='issued_on'?'date':'text'} value={draft.person_attributes[field[0]]||''} disabled={locked} oninput={e=>{if(draft)draft.person_attributes[field[0]]=e.currentTarget.value;}}/></label>{/each}</fieldset>{:else}<label class="wide-field">{t('Действующая льгота','Facilitate activă')}<select value={first.benefit_id} disabled={locked} onchange={e=>{const b=activeBenefits(project,draft!.date).find(b=>b.id===e.currentTarget.value);if(b&&draft){draft.rows=[{...administrationRow(project),benefit_id:b.id,citizen_id:b.citizen_id,account_id:b.account_id,service_id:b.service_id,category_id:b.category_id,effective_from:draft.date}];}}}><option value="">—</option>{#each activeBenefits(project,draft.date).filter(b=>!draft?.citizen_id||b.citizen_id===draft.citizen_id) as b}<option value={b.id}>{project.reference_catalogs['benefit-categories']?.find(c=>c.id===b.category_id)?.name||b.category_id} · {b.effective_from}</option>{/each}</select></label><label class="wide-field">{t('Дата прекращения','Data încetării')}<input type="date" bind:value={first.effective_from} disabled={locked}/></label>{/if}{/if}{/if}
{#if kind==='citizen-changes'}<label class="wide-field">{t('Гражданин','Persoană')}<AccountLookupField {project} kind="citizens" value={draft.citizen_id} parentId={editorId} disabled={locked} onselect={person}/></label><nav class="document-tabs"><button class:chosen={tab==='main'} onclick={()=>tab='main'}>{t('Паспортные данные','Date act de identitate')}</button><button class:chosen={tab==='family'} onclick={()=>tab='family'}>{t('Состав семьи','Componența familiei')}</button><button class:chosen={tab==='details'} onclick={()=>tab='details'}>{t('Дополнительно','Suplimentar')}</button></nav>
{#if tab==='main'}<label class="check-row"><input type="checkbox" checked={draft.person_attributes.change_passport==='true'} disabled={locked} onchange={e=>{if(draft)draft.person_attributes.change_passport=String(e.currentTarget.checked);}}/>{t('Изменить паспортные данные','Modifică datele actului')}</label>{#each [['identity_reason_id','Причина изменения паспортных данных','Motivul modificării','identity-reasons'],['identity_document_id','Вид документа','Tip document','identity-documents']] as field}<label class="wide-field">{t(field[1],field[2])}<AccountLookupField {project} kind={field[3] as 'identity-reasons'|'identity-documents'} value={draft.person_attributes[field[0]]||''} parentId={editorId} disabled={locked||draft.person_attributes.change_passport!=='true'} onselect={id=>{if(draft)draft.person_attributes[field[0]]=id;}}/></label>{/each}{#each [['identity_series','Серия','Serie'],['identity_number','Номер','Număr'],['identity_issued_on','Дата выдачи','Data eliberării'],['identity_issuer','Кем выдан','Eliberat de']] as field}<label class="wide-field">{t(field[1],field[2])}<input type={field[0]==='identity_issued_on'?'date':'text'} value={draft.person_attributes[field[0]]||''} disabled={locked||draft.person_attributes.change_passport!=='true'} oninput={e=>{if(draft)draft.person_attributes[field[0]]=e.currentTarget.value;}}/></label>{/each}
{:else if tab==='family'}<LineToolbar language={project.settings.language} disabled={locked} selected={!!draft.rows[rowIndex]} onadd={add} oncopy={()=>{if(draft&&draft.rows[rowIndex])draft.rows=[...draft.rows,{...structuredClone(draft.rows[rowIndex]),id:uid()}];}} onremove={()=>{if(draft)draft.rows=draft.rows.filter((_,i)=>i!==rowIndex);}} onmove={move} onpick={pick} onfill={fill} onclear={()=>{if(draft)draft.rows=[];}}/><div class="table-wrap"><table><thead><tr><th>№</th><th>{t('Признак вхождения','Apartenență')}</th><th>{t('Член семьи','Membru familie')}</th><th>{t('Степень родства','Relație de rudenie')}</th></tr></thead><tbody>{#each draft.rows as row,i}<tr onclick={()=>rowIndex=i} class:selected={rowIndex===i}><td>{i+1}</td><td><select bind:value={row.active} disabled={locked}><option value={true}>{t('Входит','Membru')}</option><option value={false}>{t('Не входит','Nu este membru')}</option></select></td><td><AccountLookupField {project} kind="citizens" value={row.relative_id} parentId={editorId} disabled={locked} onselect={id=>row.relative_id=id}/></td><td><AccountLookupField {project} kind="relationships" value={row.relationship_id} parentId={editorId} disabled={locked} onselect={id=>row.relationship_id=id}/></td></tr>{/each}</tbody></table></div>
{:else}<label class="wide-field">{t('ФИО','Numele complet')}<input bind:value={draft.person_name} disabled={locked}/></label>{#each catalogFields.citizens as field}<label class="wide-field">{uiLabel(field,project.settings.language,$languageOverrides)}{#if field.reference}<AccountLookupField {project} kind={field.reference} value={draft.person_attributes[field.key]||''} parentId={editorId} disabled={locked} onselect={id=>{if(draft)draft.person_attributes[field.key]=id;}}/>{:else}<input type={field.type||'text'} value={draft.person_attributes[field.key]||''} disabled={locked} oninput={e=>{if(draft)draft.person_attributes[field.key]=e.currentTarget.value;}}/>{/if}</label>{/each}{/if}
{:else if kind!=='recalculation'&&(!benefit||tab==='billing')}
<LineToolbar language={project.settings.language} disabled={locked} selected={!!draft.rows[rowIndex]} onadd={add} oncopy={()=>{if(draft&&draft.rows[rowIndex])draft.rows=[...draft.rows,{...structuredClone(draft.rows[rowIndex]),id:uid()}];}} onremove={()=>{if(draft)draft.rows=draft.rows.filter((_,i)=>i!==rowIndex);}} onmove={move} onpick={pick} onfill={['building-services','end-benefits','service-charges','recalculation','charge-corrections','penalties'].includes(kind)?fill:undefined} onclear={()=>{if(draft)draft.rows=[];}}/>
<div class="table-wrap document-lines"><table><thead><tr><th>№</th>{#if kind!=='building-services'}<th>{t('Лицевой счёт','Cont personal')}</th>{/if}{#if !charge}<th>{t('Услуга','Serviciu')}</th>{/if}{#if kind==='building-services'}<th>{t('Вид тарифа','Tip tarif')}</th><th>{t('Дата изменения','Data modificării')}</th><th>{t('Статус','Stare')}</th>{:else if kind==='grant-benefits'}<th>{t('Гражданин','Persoană')}</th><th>{t('Категория льготы','Categorie')}</th><th>{t('С даты','De la')}</th><th>{t('По дату','Până la')}</th><th>{t('Способ','Metodă')}</th><th>%</th><th>MDL</th><th>{t('Неполный месяц','Lună incompletă')}</th><th>{t('Совмещение льгот','Combinarea facilităților')}</th>{:else if kind==='end-benefits'}<th>{t('Назначение льготы','Facilitate atribuită')}</th><th>{t('Дата прекращения','Data încetării')}</th>{:else if kind==='charge-corrections'}<th>{t('Сумма, MDL','Sumă, MDL')}</th>{:else if kind==='penalties'}<th>{t('База долга, MDL','Datorie de bază, MDL')}</th><th>{t('Ставка, % в день','Rată, % pe zi')}</th><th>{t('Дней','Zile')}</th><th>{t('Пеня, MDL','Penalitate, MDL')}</th>{/if}</tr></thead><tbody>{#each draft.rows as row,i}<tr class:selected={i===rowIndex} onclick={()=>rowIndex=i}><td>{i+1}</td>{#if kind!=='building-services'}<td><AccountLookupField {project} kind="accounts" value={row.account_id} parentId={editorId} disabled={locked} onselect={id=>row.account_id=id}/></td>{/if}{#if !charge}<td><AccountLookupField {project} kind="services" value={row.service_id} parentId={editorId} disabled={locked} onselect={id=>row.service_id=id}/></td>{/if}{#if kind==='building-services'}<td><AccountLookupField {project} kind="tariff-types" value={row.tariff_type_id} parentId={editorId} disabled={locked} onselect={id=>row.tariff_type_id=id}/></td><td><input type="date" bind:value={row.effective_from} disabled={locked}/></td><td><select bind:value={row.active} disabled={locked}><option value={true}>{t('Подключена','Conectat')}</option><option value={false}>{t('Отключена','Deconectat')}</option></select></td>{:else if kind==='grant-benefits'}<td><AccountLookupField {project} kind="citizens" value={row.citizen_id} parentId={editorId} disabled={locked} onselect={id=>row.citizen_id=id}/></td><td><AccountLookupField {project} kind="benefit-categories" value={row.category_id} parentId={editorId} disabled={locked} onselect={id=>row.category_id=id}/></td><td><input type="date" bind:value={row.effective_from} disabled={locked}/></td><td><input type="date" value={row.until||''} onchange={e=>row.until=e.currentTarget.value||null} disabled={locked}/></td><td><select bind:value={row.method} disabled={locked}><option value="percent">%</option><option value="fixed">MDL</option></select></td><td><input inputmode="decimal" bind:value={row.rate} disabled={locked||row.method!=='percent'}/></td><td><input inputmode="decimal" bind:value={row.amount} disabled={locked||row.method!=='fixed'}/></td><td><select bind:value={row.proration} disabled={locked}><option value="daily">{t('Пропорционально дням','Proporțional zilelor')}</option><option value="full-month">{t('За весь месяц','Pentru luna întreagă')}</option><option value="first-day">{t('По состоянию на 1 число','La data de 1 a lunii')}</option></select></td><td><select bind:value={row.combination} disabled={locked}><option value="highest">{t('Наибольшая из льгот','Cea mai mare facilitate')}</option><option value="add">{t('Суммировать','Cumulează')}</option></select></td>{:else if kind==='end-benefits'}<td><select bind:value={row.benefit_id} disabled={locked}><option value="">—</option>{#each activeBenefits(project,draft.date) as b}<option value={b.id}>{project.reference_catalogs.citizens?.find(c=>c.id===b.citizen_id)?.name||b.citizen_id} · {b.effective_from}</option>{/each}</select></td><td><input type="date" bind:value={row.effective_from} disabled={locked}/></td>{:else if kind==='charge-corrections'}<td><input inputmode="decimal" bind:value={row.amount} disabled={locked}/></td>{:else if kind==='penalties'}<td><input inputmode="decimal" bind:value={row.quantity} disabled={locked}/></td><td><input inputmode="decimal" bind:value={row.rate} disabled={locked}/></td><td><input type="number" min="0" max="3660" bind:value={row.days} disabled={locked}/></td><td>{penaltyPreview(row.quantity,row.rate,row.days)}</td>{/if}</tr>{/each}</tbody></table></div>
{#if kind==='grant-benefits'}<p class="quiet-note">{t('Дата окончания включается в срок. Дата прекращения — первый день без льготы. По умолчанию учитываются дни действия и наибольшая льгота; итог не превышает начисление по услуге.','Data încheierii este inclusivă. Data încetării este prima zi fără facilitate. Implicit se ține cont de zile și de cea mai mare facilitate; totalul nu depășește calculul serviciului.')}</p>{/if}
{#if kind==='penalties'}<p class="quiet-note">{t('Бухгалтер указывает базу долга, дневную ставку и число дней. Сумма = база × ставка / 100 × дни.','Contabilul indică datoria de bază, rata zilnică și numărul de zile. Suma = bază × rată / 100 × zile.')}</p>{/if}
{/if}
<label class="wide-field">{t('Комментарий','Comentariu')}<input bind:value={draft.comment} disabled={locked}/></label>
<footer><button class="button secondary" onclick={()=>draft&&onmovements(draft)}><FileText size={16}/>{t('Движения','Înregistrări')}</button>{#if !locked}<button class="button" onclick={()=>save(true,true)}><Check size={16}/>OK</button><button class="button secondary" onclick={()=>save(false)}><Save size={16}/>{t('Сохранить','Salvează')}</button>{/if}<button class="button secondary" onclick={onclose}><X size={16}/>{t('Закрыть','Închide')}</button></footer>
{/if}</div>
<style>.journal-pages{display:flex;gap:12px;align-items:center}.journal-pages button{border:0;background:transparent;color:var(--text);padding:5px 10px}.document-tabs{display:flex;gap:10px}.document-tabs button{background:transparent;border:0;color:var(--text);padding:8px}.document-tabs .chosen{box-shadow:inset 0 -2px var(--accent)}fieldset{display:flex;flex-direction:column;gap:12px;border:1px solid var(--border)}.administration-documents{display:flex;flex-direction:column;gap:12px;padding:12px;min-height:100%;box-sizing:border-box}.document-head,.filters{display:flex;gap:14px;flex-wrap:wrap;align-items:center}.document-head label,.wide-field{display:flex;align-items:center;gap:12px}.wide-field{display:grid;grid-template-columns:150px minmax(0,1fr)}.document-lines{min-height:220px;flex:1}.document-lines td{min-width:145px}.document-lines td:first-child{min-width:30px}.document-lines input,.document-lines select{width:100%;box-sizing:border-box;min-width:100px;height:34px}.document-lines :global(.lookup-field){min-width:180px}.document-lines th{white-space:nowrap}.selected{background:var(--hover)}.marked{text-decoration:line-through;opacity:.6}footer{display:flex;justify-content:flex-end;gap:8px;margin-top:auto;padding-top:12px}.quiet-note{font-size:12px;color:var(--muted)}</style>
